<div class="portal-hero"><div><small>Welcome</small><h1><?= e($portalUser['name']) ?></h1><p>Track every service activity from request to invoice and warranty.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#portalRequestModal">Request Service</button></div>
<ul class="nav nav-pills mb-3 flex-nowrap overflow-auto"><li class="nav-item"><button class="nav-link active" data-bs-toggle="pill" data-bs-target="#p-requests">Requests</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="pill" data-bs-target="#p-jobs">Jobs</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="pill" data-bs-target="#p-assets">Assets</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="pill" data-bs-target="#p-quotes">Quotations</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="pill" data-bs-target="#p-invoices">Invoices</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="pill" data-bs-target="#p-contracts">Contracts & Warranty</button></li></ul>
<div class="tab-content"><div class="tab-pane fade show active" id="p-requests"><div class="portal-card-grid"><?php foreach($requests as $r): ?><div class="portal-card"><div class="d-flex justify-content-between"><strong><?= e($r['request_number']) ?></strong><span class="status-badge"><?= e($r['status']) ?></span></div><p><?= e($r['problem_description']) ?></p><small><?= e($r['request_date'].' · '.$r['priority']) ?></small></div><?php endforeach; ?></div></div><div class="tab-pane fade" id="p-jobs"><div class="portal-card-grid"><?php foreach($jobs as $j): ?><div class="portal-card"><strong><?= e($j['job_number']) ?></strong><span class="status-badge"><?= e($j['status']) ?></span><p><?= e($j['description']) ?></p><?php if(in_array($j['status'],['Completed','Customer Confirmation','Closed'],true)): ?><a class="btn btn-sm btn-outline-primary" href="<?= url('/portal/service-report/'.$j['id']) ?>">Service Report</a><?php endif; ?></div><?php endforeach; ?></div></div><div class="tab-pane fade" id="p-assets"><div class="portal-card-grid"><?php foreach($assets as $a): ?><div class="portal-card"><strong><?= e($a['asset_code']) ?></strong><p><?= e(($a['category']??'').' · '.($a['brand']??'').' '.($a['model']??'')) ?></p><small>Next service: <?= e($a['next_service']??'-') ?></small></div><?php endforeach; ?></div></div><div class="tab-pane fade" id="p-quotes"><div class="portal-card-grid"><?php foreach($quotes as $q): ?><div class="portal-card"><div class="d-flex justify-content-between"><strong><?= e($q['quotation_number']) ?></strong><span class="status-badge <?= $q['status']==='Approved'?'success':'' ?>"><?= e($q['status']) ?></span></div><h4><?= e(money($q['grand_total'])) ?></h4><div class="d-flex gap-2"><a class="btn btn-sm btn-outline-secondary" href="<?= url('/portal/quotation/'.$q['id']) ?>">PDF</a><?php if(!in_array($q['status'],['Approved','Rejected','Expired'],true)): ?><button class="btn btn-sm btn-success ajax-action" data-url="<?= url('/portal/quotations/'.$q['id'].'/approve') ?>">Approve</button><?php endif; ?></div></div><?php endforeach; ?></div></div><div class="tab-pane fade" id="p-invoices"><div class="portal-card-grid"><?php foreach($invoices as $i): ?><div class="portal-card"><div class="d-flex justify-content-between"><strong><?= e($i['invoice_number']) ?></strong><span class="status-badge <?= $i['status']==='Paid'?'success':'' ?>"><?= e($i['status']) ?></span></div><h4><?= e(money($i['balance'])) ?> balance</h4><p>Total <?= e(money($i['total'])) ?> · due <?= e($i['due_date']??'-') ?></p><a class="btn btn-sm btn-outline-secondary" href="<?= url('/portal/invoice/'.$i['id']) ?>">PDF</a> <?php if((float)$i['balance']>0): ?><button class="btn btn-sm btn-primary portal-proof-btn" data-id="<?= $i['id'] ?>" data-number="<?= e($i['invoice_number']) ?>" data-balance="<?= e($i['balance']) ?>">Upload Payment Proof</button><?php endif; ?></div><?php endforeach; ?></div></div><div class="tab-pane fade" id="p-contracts"><div class="row g-3"><div class="col-lg-6"><div class="card-panel"><h3 class="h6">Contracts</h3><?php foreach($contracts as $c): ?><div class="report-row"><span><?= e($c['contract_number']) ?><small><?= e($c['start_date'].' → '.$c['end_date']) ?></small></span><span class="status-badge"><?= e($c['status']) ?></span></div><?php endforeach; ?></div></div><div class="col-lg-6"><div class="card-panel"><h3 class="h6">Warranty</h3><?php foreach($warranties as $w): ?><div class="report-row"><span><?= e($w['job_number']) ?><small><?= e($w['coverage']??'Service warranty') ?></small></span><span class="status-badge <?= $w['status']==='Active'?'success':'' ?>"><?= e($w['warranty_end']) ?></span></div><?php endforeach; ?></div></div></div></div></div>
<div class="mt-3 card-panel"><h3 class="h6">Payment Proof History</h3><?php if(!$proofs): ?><small class="text-secondary">No payment proof submitted.</small><?php endif; ?><?php foreach($proofs as $p): ?><div class="report-row"><span><strong><?= e($p['invoice_number']) ?></strong><small><?= e($p['payment_date'].' · '.money($p['amount'])) ?></small></span><span class="status-badge <?= $p['status']==='Approved'?'success':($p['status']==='Rejected'?'danger':'') ?>"><?= e($p['status']) ?></span></div><?php endforeach; ?></div>
<div class="modal fade" id="paymentProofModal"><div class="modal-dialog"><form class="modal-content ajax-form" method="post" enctype="multipart/form-data" id="portalProofForm"><?= csrf_field() ?><div class="modal-header"><h5>Upload Payment Proof</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="alert alert-light" id="portalProofInvoice"></div><label class="form-label">Amount</label><input class="form-control mb-2" type="number" step="0.01" min="0.01" name="amount" id="portalProofAmount" required><label class="form-label">Payment Date</label><input class="form-control mb-2" type="date" name="payment_date" value="<?= date('Y-m-d') ?>"><label class="form-label">Method</label><select class="form-select mb-2" name="payment_method"><option>Bank Transfer</option><option>QRIS</option><option>Cash</option><option>Credit Card</option><option>Other</option></select><input class="form-control mb-2" name="bank" placeholder="Bank / provider"><input class="form-control mb-2" name="reference" placeholder="Reference"><label class="form-label">Proof</label><input class="form-control mb-2" type="file" name="attachment" accept="image/jpeg,image/png,application/pdf" required><textarea class="form-control" name="notes" placeholder="Notes"></textarea></div><div class="modal-footer"><button class="btn btn-primary">Submit Proof</button></div></form></div></div>
<div class="modal fade" id="portalRequestModal"><div class="modal-dialog"><form class="modal-content ajax-form" method="post" action="<?= url('/portal/requests') ?>"><?= csrf_field() ?><div class="modal-header"><h5>Request Service</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label">Site</label><select class="form-select mb-2" name="site_id"><option value="">Default site</option><?php foreach($sites as $s): ?><option value="<?= $s['id'] ?>"><?= e($s['site_name']) ?></option><?php endforeach; ?></select><input class="form-control mb-2" name="service_category" placeholder="Service category"><select class="form-select mb-2" name="priority"><option>Low</option><option selected>Normal</option><option>High</option><option>Urgent</option><option>Emergency</option></select><textarea class="form-control" name="problem_description" rows="5" placeholder="Describe the problem" required></textarea></div><div class="modal-footer"><button class="btn btn-primary">Submit Request</button></div></form></div></div>
